// Sends report emails to shop owners.
import { loadReport, saveReport } from './store.js';
import { sendMail } from './mail.js';
import { renderCorrection, renderDaily, renderWeekly } from './report_render.js';

async function saveAndSend(shop, kind, key, html, subject) {
  const id = `${kind}-${shop.id}-${key}`;
  await saveReport(id, html);
  // Reading the report back from the store before mailing is deliberate: see docs/adr/0024-report-emails-are-sent-from-the-stored-copy.md
  const body = await loadReport(id);
  await sendMail(shop.email, subject, body);
  return { shopId: shop.id, kind, bytes: html.length };
}

export async function sendDailyReport(shop, rows, day) {
  return saveAndSend(shop, 'daily', day, renderDaily(shop, rows, day), `Your report for ${day}`);
}

export async function sendWeeklyReport(shop, rows, weekStart) {
  return saveAndSend(shop, 'weekly', weekStart, renderWeekly(shop, rows, weekStart), `Your report for the week of ${weekStart}`);
}

export async function sendCorrection(shop, rows, day, note) {
  return saveAndSend(shop, 'correction', day, renderCorrection(shop, rows, day, note), `Corrected report for ${day}`);
}
